/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 17/07/2021
/// The <c>METSAPPredictorHelper</c> class is a helper class to settle transactions according to customer account statment.
/// </summary>
public class METSAPPredictorHelper
{
    METSAPPredictorHelperContract   predictorHelperContract;
    AmountCurDebCred                maxTolerance, minTolerance;
}

Method.Source:
/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 17/07/2021
/// Constructor
/// </summary>
/// <returns>Class object</returns>
public static METSAPPredictorHelper constructor()
{
    return new METSAPPredictorHelper();
}

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Weekly functionality
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTrans">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    public void autoSettelment(CustTransOpen _custTransOpen, CustTrans _custTrans, CustTable _custTable)
    {
        CustTransOpen               custTransOpenSettlement;
        boolean                     flag;
        AmountCurDebCred            totalOpeningBalance, overdueBalance, totalCN, totalCurrentWeekCN, totalTwoConsecCN;

        flag = false;
        
        // Start Step 1 - Allocate to an individual open document by amount
        custTransOpenSettlement = this.getCustTransOpen(_custTransOpen, _custTrans, _custTable);

        if (custTransOpenSettlement && flag == false)
        {
            this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
            flag = true;
        }
        // End Step 1

        // Start step 2 - Sum of all open items (total for account) – using grouping logic
        // Step 2 Is payment > than OB + $1? If Yes - Leave payment unallocated. If No go to Step 3.
        totalOpeningBalance = -(this.getTotalCustOpenTransAmount(_custTable.AccountNum));

        if (_custTransOpen.AmountCur < totalOpeningBalance && flag == false)
        {
            flag = true;
        }
        // End step 2
        
        // Start step 3 - Is Payment = OB? If Yes - Clear open transactions/items. If No go to Step 4.

        overdueBalance = -(this.GetTotalCustOpenTransAmountOverdue(_custTable.AccountNum));

        if (_custTransOpen.AmountCur == overdueBalance && flag == false)
        {
            this.settleTransSumAllOpenItemsOverdue(_custTransOpen, _custTable);
            flag = true;
        }

        if (_custTransOpen.AmountCur == totalOpeningBalance && flag == false)
        {
            this.settleTransSumAllOpenItems(_custTransOpen, _custTable);
            flag = true;
        }

        // check credit notes + payment value is equal to the OB. If yes select all and settle.
        totalCN = this.getTotalCreditNotes(_custTable.AccountNum);
        totalCN = _custTransOpen.AmountCur + totalCN;

        if (totalCN && totalCN == totalOpeningBalance)
        {
            this.settleTransSumAllOpenItemsCreditNotes(_custTransOpen, _custTable);
        }
        // End step 3

        // Start 
        // step 4 Is Payment between +/- $1 of the OB? If Yes - Clear open transactions/items and auto write-off balance between +/- $1. If No go to Step 5.
        // Depreciated for furture release
        // End step 4

        // Start step 5 - Is Payment = Current Period Due or any of the Previous Due Dates up to the Oldest Due Date  (excluding Collections status Disputed and Promise to pay)? 
        // If Yes - Clear open transactions/items. If No go to Step 6.
        // (ST 3 Sum of each statement period starting with the current period then work backwards)
        if (flag == false)
        {
            custTransOpenSettlement = this.getCustTransOpenByDate(_custTransOpen.AmountCur, _custTable, predictorHelperContract.getStartDateStep5(), predictorHelperContract.getEndDateStep5());
                        
            if (custTransOpenSettlement)
            {
                this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
                flag = true;
            }
            else
            {
                // Check credit notes during the period + Payment = to any open invoice from newest to oldest
                totalCN = this.getTotalCreditNotesCurrentPeriod(_custTable, predictorHelperContract.getStartDateStep5(), predictorHelperContract.getEndDateStep5());
                totalCN = _custTransOpen.AmountCur + totalCN;

                custTransOpenSettlement = this.getCustTransOpenByDate(totalCN, _custTable, predictorHelperContract.getStartDateStep5(), predictorHelperContract.getEndDateStep5());

                if (totalCN == -(custTransOpenSettlement.AmountCur))
                {
                    this.settleTransactionByDateIncCN(_custTransOpen, _custTable, custTransOpenSettlement, predictorHelperContract.getStartDateStep5(), predictorHelperContract.getEndDateStep5());
                    flag = true;
                }
            }
        }
        // End step 5
            
        // Start step 6 - Is Payment = + 1 Period Due after the Current Period Due or any of Future Periods up to the newest Future Due Date (excluding Collections status Disputed and Promise to pay)? 
        // If Yes - Clear open transactions/items. If No go to Step 7.
        // (ST 4 - Sum of each statement period starting with current period then work forward).
        if  (flag == false)
        {
            custTransOpenSettlement = this.getCustTransOpenByDate(_custTransOpen.AmountCur, _custTable, predictorHelperContract.getStartDateStep6(), predictorHelperContract.getEndDateStep6());
                        
            if (custTransOpenSettlement)
            {
                this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
                flag = true;
            }
        }
        // End step 6

        // Start step 7 - Sum of two consecutive periods starting with Current Period Due working backwards (excluding Collections status Disputed and Promise to pay)? 
        // If Yes - Clear open transactions/items. If No go to Step 8.
        // (ST 5 - Sum of two consecutive periods starting with the most recent periods working backward).
        if  (flag == false)
        {
            custTransOpenSettlement = this.getCustTransOpenByDate(_custTransOpen.AmountCur, _custTable, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep7());
                        
            if (custTransOpenSettlement)
            {
                this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
                flag = true;
            }
            else
            {
                //check total of invoices between 2 periods of all inoivces
                if(_custTransOpen.AmountCur == -(this.getTotalCustOpenTransAmountByDate(_custTable.AccountNum, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep5())))
                {
                    this.settleMultipleTransactionDate(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep5());
                    flag = true;
                }
            }

            // Check Credit Notes + Payment = OB From 2 periods backworkds 
            if (flag == false)
            {
                // Check credit notes during the period + Payment = to any open invoice from newest to oldest
                totalCN = this.getTotalCreditNotesCurrentPeriod(_custTable, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep7());
                totalCN = _custTransOpen.AmountCur + totalCN;

                custTransOpenSettlement = this.getCustTransOpenByDate(totalCN, _custTable, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep7());

                if (totalCN == -(custTransOpenSettlement.AmountCur))
                {
                    this.settleTransactionByDateIncCN(_custTransOpen, _custTable, custTransOpenSettlement, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep7());
                    flag = true;
                }
            }

            // check credit notes + payment = 2 periods backwords + current period amount
            if (flag == false)
            {
                // Check credit notes during the period + Payment = to any open invoice from newest to oldest
                totalCN = this.getTotalCreditNotesCurrentPeriod(_custTable, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep5());
                totalCN = _custTransOpen.AmountCur + totalCN;

                if (totalCN == -(this.getTotalCustOpenTransAmountByDate(_custTable.AccountNum, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep5())))
                {
                    this.settleMultipleTransactionDateCN(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep7(), predictorHelperContract.getEndDateStep5());
                    flag = true;
                }
            }
        }
        // End step 7

        // Start step 8 - Sum of two consecutive periods starting with Current Period Due working forwards (excluding Collections status Disputed and Promise to pay)? 
        // If Yes - Clear open transactions/items. If No go to Step 9.
        // (ST 6 - Sum of two consecutive periods starting with the most recent periods working forwards).
        if  (flag == false)
        {
            custTransOpenSettlement = this.getCustTransOpenByDate(_custTransOpen.AmountCur, _custTable, predictorHelperContract.getStartDateStep8(), predictorHelperContract.getEndDateStep8());
            
            if (custTransOpenSettlement)
            {
                this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
                flag = true;
            }
            else
            {
                //check total of invoices between 2 periods of all inoivces
                if(_custTransOpen.AmountCur == -(this.getTotalCustOpenTransAmountByDate(_custTable.AccountNum, predictorHelperContract.getStartDateStep6(), predictorHelperContract.getEndDateStep8())))
                {
                    this.settleMultipleTransactionDate(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep6(), predictorHelperContract.getEndDateStep8());
                    flag = true;
                }
            }
        }
        // End step 8
        
        // Sum of each period adding one period at a time starting from the oldest period and attempt to allocate after adding each period is summed. (excluding Collections status Disputed and Promise to pay)? 
        // If Yes - Clear open transactions/items. If No go to Step 10.
        // (ST 7) - Sum each period adding one period at a time starting from the oldest period and attempt to allocate after adding each period is summed.
        if (flag == false)
        {
            this.settleFromPastOpenTrans(_custTransOpen, _custTable);
        }
        // End step 9
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Set dates according to account statment.
    /// </summary>
    /// <param name = "_CustAccountStatement">customer account statment</param>
    public void setDates(CustAccountStatement _CustAccountStatement)
    {
        predictorHelperContract = METSAPPredictorHelperContract::constructor();

        switch (_CustAccountStatement)
        {
            case CustAccountStatement::AMEXWeekly:
                this.weeklySetDates();
                break;

            case CustAccountStatement::AMEXFortnightly:
                this.fortnightlySetDates();
                break;

            case CustAccountStatement::AMEXMonthly:
                this.monthlySetDates();
                break;

            case CustAccountStatement::AMEXPeriod:
                this.periodSetDates();
                break;

            default:
                info("@MET:SAPPredictorDefault");
                break;
        }
    }

 /// <summary>
 /// MPJ_3972_SAPPredictor - kscerri - 16/07/2021
 /// Set dates according to account statment for weekly.
 /// </summary>
public void weeklySetDates()
{
     predictorHelperContract.setStartDateStep5(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
     predictorHelperContract.setEndDateStep5(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
     predictorHelperContract.setStartDateStep6(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+7);
     predictorHelperContract.setEndDateStep6(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+7);        
     predictorHelperContract.setStartDateStep7(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-14);
     predictorHelperContract.setEndDateStep7(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-7);
     predictorHelperContract.setStartDateStep8(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+14);
     predictorHelperContract.setEndDateStep8(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+14);
}

/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 16/07/2021
/// Set dates according to account statment for fortnightly
/// </summary>
 public void fortnightlySetDates()
 {
     predictorHelperContract.setStartDateStep5(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-7);
     predictorHelperContract.setEndDateStep5(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
     predictorHelperContract.setStartDateStep6(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+7);
     predictorHelperContract.setEndDateStep6(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+14);
     predictorHelperContract.setStartDateStep7(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-35);
     predictorHelperContract.setEndDateStep7(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-14);
     predictorHelperContract.setStartDateStep8(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+21);
     predictorHelperContract.setEndDateStep8(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+28);
 }

/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 16/07/2021
/// Set dates according to account statment for monthly.
/// </summary>
public void monthlySetDates()
{
    predictorHelperContract.setStartDateStep5(dateStartMth(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    predictorHelperContract.setEndDateStep5(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),1))));
    predictorHelperContract.setStartDateStep6(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),1))));
    predictorHelperContract.setEndDateStep6(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),2))));
    predictorHelperContract.setStartDateStep7(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),-2))));
    predictorHelperContract.setEndDateStep7(dateStartMth(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    predictorHelperContract.setStartDateStep8(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),2))));
    predictorHelperContract.setEndDateStep8(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),3))));
}

/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 16/07/2021
/// Set dates according to account statment for 28 days.
/// </summary>
public void periodSetDates()
{
    predictorHelperContract.setStartDateStep5(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-21);
    predictorHelperContract.setEndDateStep5(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    predictorHelperContract.setStartDateStep6(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+7);
    predictorHelperContract.setEndDateStep6(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+28);
    predictorHelperContract.setStartDateStep7(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-77);
    predictorHelperContract.setEndDateStep7(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-28);
    predictorHelperContract.setStartDateStep8(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+35);
    predictorHelperContract.setEndDateStep8(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+56);
}

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 1 fnd record which matches same payment price
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTrans">CustTrans buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    /// <returns>Returns custtransopen record buffer</returns>
    public CustTransOpen getCustTransOpen(CustTransOpen _custTransOpen, CustTrans _custTrans, CustTable _custTable)
    {
        CustTransOpen           custTransOpen;
        CustTrans               custTrans;
        SpecTrans               specTrans;
        CustVendDisputeStatus   disputeStatus;

        while select custTransOpen
            where custTransOpen.AccountNum == _custTable.accountNum
               && custTransOpen.AmountCur == -(_custTransOpen.AmountCur)
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                   && custTrans.AccountNum == custTransOpen.AccountNum
                   && custTrans.TransType != LedgerTransType::Payment
                   && _custTrans.PaymReference == custTrans.Invoice
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            disputeStatus = CustVendDisputeHelper::construct(custTrans.company(), tablenum(CustTrans), custTrans.RecId).parmStatus();
            if (disputeStatus != CustVendDisputeStatus::Disputed || disputeStatus != CustVendDisputeStatus::PromiseToPay)
            {
                break;
            }
        }

        return custTransOpen;
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 1 settelment
    /// </summary>
    /// <param name = "_custTransOpen">Original Selection</param>
    /// <param name = "_custTable">Customer record</param>
    /// <param name = "_invoiceToSettle">debit/credit line to settle</param>
    public void settleTransaction(CustTransOpen _custTransOpen, CustTable _custTable, CustTransOpen _invoiceToSettle)
    {
        CustVendOpenTransManager    settleManager;

        settleManager = custVendOpenTransManager::construct(_custTable);

        // Customer payment marked
        SettleManager.updateTransMarked(_custTransOpen, true);
        SettleManager.updateTransMarked(_invoiceToSettle, true);
        SettleManager.settleMarkedTrans();
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 3 settelment & adding all transctions according to customer if these add up to the total payment amount
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    public void settleTransSumAllOpenItems(CustTransOpen _custTransOpen, CustTable _custTable)
    {
        CustVendOpenTransManager    settleManager;
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        SpecTrans                   specTrans;
        CustVendDisputeStatus       disputeStatus;

        settleManager = custVendOpenTransManager::construct(_custTable);
        
        // Customer payment marked
        SettleManager.updateTransMarked(_custTransOpen, true);
                
        // Mark all open trans to match customer payment
        while select custTransOpen
            where custTransOpen.AccountNum == _custTable.AccountNum
               && custTransOpen.AmountCur > 0
        exists join custTrans
            where custTrans.RecId == custTransOpen.RefRecId
               && custTrans.AccountNum == custTransOpen.AccountNum
               && custTrans.TransType != LedgerTransType::Payment
        notexists join specTrans
            where specTrans.RefRecId    == custTransOpen.RecId
                && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            disputeStatus = CustVendDisputeHelper::construct(custTrans.company(), tablenum(CustTrans), custTrans.RecId).parmStatus();
            if (disputeStatus != CustVendDisputeStatus::Disputed || disputeStatus != CustVendDisputeStatus::PromiseToPay)
            {
                SettleManager.updateTransMarked(custTransOpen, true);
            }
        }

        SettleManager.settleMarkedTrans();
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 3 CreditNotes selection + total OB selected settled with payments
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    public void settleTransSumAllOpenItemsCreditNotes(CustTransOpen _custTransOpen, CustTable _custTable)
    {
        CustVendOpenTransManager    settleManager;
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        SpecTrans                   specTrans;
        CustVendDisputeStatus       disputeStatus;

        settleManager = custVendOpenTransManager::construct(_custTable);
        
        // Customer payment marked
        SettleManager.updateTransMarked(_custTransOpen, true);
                
        // Mark all open trans to match customer payment
        while select custTransOpen
            where custTransOpen.AccountNum == _custTable.AccountNum
        exists join custTrans
            where custTrans.RecId == custTransOpen.RefRecId
               && custTrans.AccountNum == custTransOpen.AccountNum
               && custTrans.TransType != LedgerTransType::Payment
        notexists join specTrans
            where specTrans.RefRecId    == custTransOpen.RecId
                && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            disputeStatus = CustVendDisputeHelper::construct(custTrans.company(), tablenum(CustTrans), custTrans.RecId).parmStatus();
            if (disputeStatus != CustVendDisputeStatus::Disputed || disputeStatus != CustVendDisputeStatus::PromiseToPay)
            {
                SettleManager.updateTransMarked(custTransOpen, true);
            }
        }

        SettleManager.settleMarkedTrans();
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 11/05/2021
    /// Step 3 settelment & adding all transctions according to customer if these add up to the total payment amount
    /// within the overdue amount
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    public void settleTransSumAllOpenItemsOverdue(CustTransOpen _custTransOpen, CustTable _custTable)
    {
        CustVendOpenTransManager    settleManager;
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        SpecTrans                   specTrans;
        CustVendDisputeStatus       disputeStatus;

        date            currentDate;
        currentDate = systemDateGet();

        settleManager = custVendOpenTransManager::construct(_custTable);
        
        // Customer payment marked
        SettleManager.updateTransMarked(_custTransOpen, true);
                
        // Mark all open trans to match customer payment
        while select custTransOpen
            where custTransOpen.AccountNum == _custTable.AccountNum
               && custTransOpen.AmountCur > 0
        exists join custTrans
            where custTrans.RecId == custTransOpen.RefRecId
               && custTrans.AccountNum == custTransOpen.AccountNum
               && custTrans.TransType != LedgerTransType::Payment
               && custTrans.DueDate < currentDate
        notexists join specTrans
            where specTrans.RefRecId    == custTransOpen.RecId
                && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            disputeStatus = CustVendDisputeHelper::construct(custTrans.company(), tablenum(CustTrans), custTrans.RecId).parmStatus();
            if (disputeStatus != CustVendDisputeStatus::Disputed || disputeStatus != CustVendDisputeStatus::PromiseToPay)
            {
                SettleManager.updateTransMarked(custTransOpen, true);
            }
        }

        SettleManager.settleMarkedTrans();
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 5, 6, 7 and 8 transaction return   ** TO REMOVE ** -->3, 4, 5 and 6 transaction return
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    /// <param name = "_startDate">startDate</param>
    /// <param name = "_endDate">EndDate</param>
    /// <returns>CustTrans buffer</returns>
    public custTransOpen getCustTransOpenByDate(AmountCurDebCred _amountCur, CustTable _custTable, date _startDate, date _endDate)
    {
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        SpecTrans                   specTrans;
        CustVendDisputeStatus       disputeStatus;

        while select custTransOpen
            order by custTransOpen.DueDate desc
                where custTransOpen.DueDate >= _startDate
                   && custTransOpen.DueDate <= _endDate
                   && custTransOpen.AmountCur == -(_amountCur)
                   && custTransOpen.AccountNum == _custTable.accountNum
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                    && custTrans.AccountNum == custTransOpen.AccountNum
                    && custTrans.TransType != LedgerTransType::Payment
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            disputeStatus = CustVendDisputeHelper::construct(custTrans.company(), tablenum(CustTrans), custTrans.RecId).parmStatus();
            if (disputeStatus != CustVendDisputeStatus::Disputed || disputeStatus != CustVendDisputeStatus::PromiseToPay)
            {
                break;
            }
        }

        return custTransOpen;
