    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 5 settelment with CN
    /// </summary>
    /// <param name = "_custTransOpen">Original Selection</param>
    /// <param name = "_custTable">Customer record</param>
    /// <param name = "_invoiceToSettle">debit/credit line to settle</param>
    public void settleTransactionByDateIncCN(CustTransOpen _custTransOpen, CustTable _custTable, CustTransOpen _invoiceToSettle, date _startDate, date _endDate)
    {
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        SpecTrans                   specTrans;
        CustVendDisputeStatus       disputeStatus;
        CustVendOpenTransManager    settleManager;

        settleManager = custVendOpenTransManager::construct(_custTable);

        // Customer payment marked and open trans
        SettleManager.updateTransMarked(_custTransOpen, true);
        SettleManager.updateTransMarked(_invoiceToSettle, true);

        // Marking credit notes
        while select custTransOpen
            order by custTransOpen.DueDate desc
                where custTransOpen.DueDate >= _startDate
                   && custTransOpen.DueDate <= _endDate
                   && custTransOpen.AccountNum == _custTable.accountNum
                   && custTransOpen.AmountCur < 0
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                    && custTrans.AccountNum == custTransOpen.AccountNum
                    && custTrans.TransType == LedgerTransType::Cust
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            disputeStatus = CustVendDisputeHelper::construct(custTrans.company(), tablenum(CustTrans), custTrans.RecId).parmStatus();
            if (disputeStatus != CustVendDisputeStatus::Disputed || disputeStatus != CustVendDisputeStatus::PromiseToPay)
            {
                SettleManager.updateTransMarked(custTransOpen, true);
            }
        }

        SettleManager.settleMarkedTrans();
    }

