    /// Returns total amount of open cust trans depending on customer acc which are over due (step 3)
    /// </summary>
    /// <param name = "_accountNum">account num</param>
    /// <returns>total amount cur</returns>
    public AmountCurDebCred GetTotalCustOpenTransAmountOverdue(CustAccount _accountNum)
    {
        CustTransOpen           custTransOpen;
        CustTrans               custTrans;
        SpecTrans               specTrans;
        CustVendDisputeStatus   disputeStatus;
        AmountCurDebCred        amoundCurSum;

        date            currentDate;
        currentDate = systemDateGet();


        while select AmountCur from custTransOpen
            where custTransOpen.AccountNum == _accountNum
               && custTransOpen.AmountCur > 0
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                    && custTrans.AccountNum == custTransOpen.AccountNum
                    && custTrans.TransType != LedgerTransType::Payment
                    && custTrans.DueDate < currentDate
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            disputeStatus = CustVendDisputeHelper::construct(custTrans.company(), tablenum(CustTrans), custTrans.RecId).parmStatus();
            if (disputeStatus != CustVendDisputeStatus::Disputed || disputeStatus != CustVendDisputeStatus::PromiseToPay)
            {
                amoundCurSum = amoundCurSum + custTransOpen.AmountCur;
            }
        }

        return amoundCurSum;
    }

